"""
Cliente da Instagram Graph API com retry, rate limiting e logging integrados.

Uso:
    from api_client import InstagramAPI

    api = InstagramAPI()
    profile = await api.get_user_profile()
    media = await api.get_user_media(limit=10)
    await api.close()
"""
from __future__ import annotations

import asyncio
import json
import logging
import sys
from pathlib import Path
from typing import Any, Dict, List, Optional

sys.path.insert(0, str(Path(__file__).parent))

import httpx

from config import (
    GRAPH_API_BASE,
    IMGUR_CLIENT_ID,
    IMGUR_UPLOAD_URL,
    MAX_RETRIES,
    REQUEST_TIMEOUT,
    RETRY_BACKOFF_BASE,
)
from db import Database
from governance import GovernanceManager, RateLimitExceeded

logger = logging.getLogger(__name__)


class InstagramAPIError(Exception):
    """Erro da Instagram Graph API."""

    def __init__(self, message: str, code: Optional[int] = None, subcode: Optional[int] = None):
        self.code = code
        self.subcode = subcode
        super().__init__(message)

    def is_rate_limit(self) -> bool:
        return self.code in (4, 17, 32)

    def is_permission_error(self) -> bool:
        return self.code in (10, 200, 190)


class InstagramAPI:
    """Wrapper da Instagram Graph API com governança integrada."""

    def __init__(
        self,
        account_id: Optional[int] = None,
        db: Optional[Database] = None,
        governance: Optional[GovernanceManager] = None,
    ):
        self._db = db or Database()
        self._db.init()
        self._gov = governance or GovernanceManager(self._db)
        self._client: Optional[httpx.AsyncClient] = None

        # Carregar conta
        if account_id:
            self._account = self._db.get_account_by_id(account_id)
        else:
            self._account = self._db.get_active_account()

        if not self._account:
            raise ValueError(
                "Nenhuma conta Instagram configurada. Execute: python scripts/auth.py --setup"
            )

        self.account_id = self._account["id"]
        self.ig_user_id = self._account["ig_user_id"]
        self.access_token = self._account["access_token"]

    async def _get_client(self) -> httpx.AsyncClient:
        if self._client is None or self._client.is_closed:
            self._client = httpx.AsyncClient(timeout=REQUEST_TIMEOUT)
        return self._client

    async def close(self) -> None:
        if self._client and not self._client.is_closed:
            await self._client.aclose()

    # ── Core Request ──────────────────────────────────────────────────────────

    async def _request(
        self,
        method: str,
        endpoint: str,
        params: Optional[Dict] = None,
        data: Optional[Dict] = None,
        action_name: str = "api_call",
    ) -> Dict[str, Any]:
        """
        Faz request à Graph API com retry, rate limiting e logging.
        """
        # Verificar rate limit
        self._gov.check_rate_limit(action_name, self.account_id)

        url = f"{GRAPH_API_BASE}/{endpoint}" if not endpoint.startswith("http") else endpoint
        params = params or {}
        params["access_token"] = self.access_token

        client = await self._get_client()

        for attempt in range(1, MAX_RETRIES + 1):
            try:
                if method.upper() == "POST":
                    resp = await client.post(url, params=params, data=data)
                elif method.upper() == "DELETE":
                    resp = await client.delete(url, params=params)
                else:
                    resp = await client.get(url, params=params)

                # Parse response
                result = resp.json()

                # Verificar erro da API
                if "error" in result:
                    error = result["error"]
                    api_error = InstagramAPIError(
                        message=error.get("message", "Unknown error"),
                        code=error.get("code"),
                        subcode=error.get("error_subcode"),
                    )
                    if api_error.is_rate_limit():
                        logger.warning("Rate limit da API atingido (code %s). Aguardando...", api_error.code)
                        if attempt < MAX_RETRIES:
                            await asyncio.sleep(60)  # espera 1 min para rate limits da API
                            continue
                    if api_error.is_permission_error():
                        raise api_error  # não faz retry para erros de permissão
                    if attempt < MAX_RETRIES:
                        await asyncio.sleep(RETRY_BACKOFF_BASE ** attempt)
                        continue
                    raise api_error

                resp.raise_for_status()

                # Log da ação
                self._gov.log_action(
                    action=action_name,
                    params={"endpoint": endpoint, "method": method},
                    result={"status": resp.status_code},
                    account_id=self.account_id,
                )

                return result

            except httpx.HTTPStatusError as exc:
                logger.warning(
                    "HTTP %s em %s (tentativa %d/%d)",
                    exc.response.status_code, url, attempt, MAX_RETRIES,
                )
                if attempt < MAX_RETRIES:
                    await asyncio.sleep(RETRY_BACKOFF_BASE ** attempt)
                else:
                    raise

            except (httpx.RequestError, httpx.TimeoutException) as exc:
                logger.warning(
                    "Erro de request em %s: %s (tentativa %d/%d)",
                    url, exc, attempt, MAX_RETRIES,
                )
                if attempt < MAX_RETRIES:
                    await asyncio.sleep(RETRY_BACKOFF_BASE ** attempt)
                else:
                    raise

        raise InstagramAPIError("Falha após todas as tentativas")

    async def get(self, endpoint: str, params: Optional[Dict] = None, action: str = "api_get") -> Dict:
        return await self._request("GET", endpoint, params=params, action_name=action)

    async def post(self, endpoint: str, data: Optional[Dict] = None, params: Optional[Dict] = None, action: str = "api_post") -> Dict:
        return await self._request("POST", endpoint, params=params, data=data, action_name=action)

    async def delete(self, endpoint: str, params: Optional[Dict] = None, action: str = "api_delete") -> Dict:
        return await self._request("DELETE", endpoint, params=params, action_name=action)

    # ── User / Profile ────────────────────────────────────────────────────────

    async def get_user_profile(self) -> Dict[str, Any]:
        """Busca informações do perfil da conta Instagram."""
        return await self.get(
            f"{self.ig_user_id}",
            params={
                "fields": "id,username,name,account_type,profile_picture_url,"
                          "biography,followers_count,follows_count,media_count,website",
            },
            action="get_profile",
        )

    # ── Media ─────────────────────────────────────────────────────────────────

    async def get_user_media(
        self, limit: int = 25, after: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Lista mídia do usuário com paginação."""
        params = {
            "fields": "id,caption,media_type,media_url,thumbnail_url,permalink,"
                      "timestamp,like_count,comments_count",
            "limit": str(limit),
        }
        if after:
            params["after"] = after
        return await self.get(f"{self.ig_user_id}/media", params=params, action="get_media")

    async def get_media_details(self, media_id: str) -> Dict[str, Any]:
        """Busca detalhes de uma mídia específica."""
        return await self.get(
            media_id,
            params={
                "fields": "id,caption,media_type,media_url,thumbnail_url,permalink,"
                          "timestamp,like_count,comments_count,children{id,media_type,media_url}",
            },
            action="get_media_details",
        )

    # ── Publishing (2-step) ───────────────────────────────────────────────────

    async def create_media_container(
        self,
        media_type: str = "IMAGE",
        image_url: Optional[str] = None,
        video_url: Optional[str] = None,
        caption: Optional[str] = None,
        location_id: Optional[str] = None,
        user_tags: Optional[List[Dict]] = None,
        is_carousel_item: bool = False,
        cover_url: Optional[str] = None,
        share_to_feed: bool = True,
        children: Optional[List[str]] = None,
    ) -> Dict[str, Any]:
        """Cria container de mídia (step 1 do publish)."""
        data: Dict[str, Any] = {}

        if media_type == "IMAGE":
            data["image_url"] = image_url
        elif media_type == "VIDEO":
            data["media_type"] = "VIDEO"
            data["video_url"] = video_url
        elif media_type == "REELS":
            data["media_type"] = "REELS"
            data["video_url"] = video_url
            if cover_url:
                data["cover_url"] = cover_url
            data["share_to_feed"] = str(share_to_feed).lower()
        elif media_type == "STORIES":
            if image_url:
                data["image_url"] = image_url
            elif video_url:
                data["video_url"] = video_url
                data["media_type"] = "VIDEO"
        elif media_type == "CAROUSEL":
            data["media_type"] = "CAROUSEL"
            if children:
                data["children"] = ",".join(children)

        if caption and not is_carousel_item:
            data["caption"] = caption
        if location_id:
            data["location_id"] = location_id
        if user_tags:
            data["user_tags"] = json.dumps(user_tags)
        if is_carousel_item:
            data["is_carousel_item"] = "true"

        return await self.post(
            f"{self.ig_user_id}/media",
            data=data,
            action=f"create_container_{media_type.lower()}",
        )

    async def check_container_status(self, container_id: str) -> Dict[str, Any]:
        """Verifica status de um container (usado para vídeos que precisam processar)."""
        return await self.get(
            container_id,
            params={"fields": "status_code,status"},
            action="check_container",
        )

    async def publish_media(self, container_id: str) -> Dict[str, Any]:
        """Publica um container (step 2 do publish)."""
        return await self.post(
            f"{self.ig_user_id}/media_publish",
            data={"creation_id": container_id},
            action="publish_media",
        )

    # ── Comments ──────────────────────────────────────────────────────────────

    async def get_comments(
        self, media_id: str, limit: int = 50, after: Optional[str] = None,
    ) -> Dict[str, Any]:
        params = {
            "fields": "id,text,username,timestamp,replies{id,text,username,timestamp}",
            "limit": str(limit),
        }
        if after:
            params["after"] = after
        return await self.get(f"{media_id}/comments", params=params, action="get_comments")

    async def reply_to_comment(self, comment_id: str, text: str) -> Dict[str, Any]:
        return await self.post(
            f"{comment_id}/replies",
            data={"message": text},
            action="reply_comment",
        )

    async def delete_comment(self, comment_id: str) -> Dict[str, Any]:
        return await self.delete(comment_id, action="delete_comment")

    async def get_mentions(self, limit: int = 25) -> Dict[str, Any]:
        return await self.get(
            f"{self.ig_user_id}/tags",
            params={"fields": "id,caption,media_type,permalink,timestamp", "limit": str(limit)},
            action="get_mentions",
        )

    # ── Insights ──────────────────────────────────────────────────────────────

    async def get_media_insights(
        self, media_id: str, metrics: Optional[List[str]] = None,
    ) -> Dict[str, Any]:
        if not metrics:
            metrics = ["impressions", "reach", "engagement", "saved", "shares"]
        return await self.get(
            f"{media_id}/insights",
            params={"metric": ",".join(metrics)},
            action="get_media_insights",
        )

    async def get_user_insights(
        self,
        period: str = "day",
        metrics: Optional[List[str]] = None,
        since: Optional[str] = None,
        until: Optional[str] = None,
    ) -> Dict[str, Any]:
        if not metrics:
            metrics = ["impressions", "reach", "follower_count", "profile_views"]
        params: Dict[str, str] = {
            "metric": ",".join(metrics),
            "period": period,
        }
        if since:
            params["since"] = since
        if until:
            params["until"] = until
        return await self.get(
            f"{self.ig_user_id}/insights",
            params=params,
            action="get_user_insights",
        )

    # ── Hashtags ──────────────────────────────────────────────────────────────

    async def search_hashtag(self, hashtag: str) -> Dict[str, Any]:
        """Busca o ID de uma hashtag."""
        return await self.get(
            "ig_hashtag_search",
            params={"q": hashtag, "user_id": self.ig_user_id},
            action="search_hashtag",
        )

    async def get_hashtag_recent_media(
        self, hashtag_id: str, limit: int = 25,
    ) -> Dict[str, Any]:
        return await self.get(
            f"{hashtag_id}/recent_media",
            params={
                "user_id": self.ig_user_id,
                "fields": "id,caption,media_type,permalink,timestamp,like_count,comments_count",
                "limit": str(limit),
            },
            action="get_hashtag_media",
        )

    async def get_hashtag_top_media(
        self, hashtag_id: str, limit: int = 25,
    ) -> Dict[str, Any]:
        return await self.get(
            f"{hashtag_id}/top_media",
            params={
                "user_id": self.ig_user_id,
                "fields": "id,caption,media_type,permalink,timestamp,like_count,comments_count",
                "limit": str(limit),
            },
            action="get_hashtag_top",
        )

    # ── Messaging ─────────────────────────────────────────────────────────────

    async def send_message(self, recipient_id: str, text: str) -> Dict[str, Any]:
        return await self.post(
            f"{self.ig_user_id}/messages",
            data={
                "recipient": json.dumps({"id": recipient_id}),
                "message": json.dumps({"text": text}),
            },
            action="send_dm",
        )

    async def get_conversations(self, limit: int = 20) -> Dict[str, Any]:
        return await self.get(
            f"{self.ig_user_id}/conversations",
            params={
                "fields": "id,participants,updated_time",
                "limit": str(limit),
                "platform": "instagram",
            },
            action="get_conversations",
        )

    # ── Imgur Upload (mídia local → URL pública) ──────────────────────────────

    async def upload_to_imgur(self, file_path: str) -> str:
        """
        Faz upload de arquivo local para o Imgur (anônimo).
        Retorna a URL pública da imagem.
        """
        client = await self._get_client()
        with open(file_path, "rb") as f:
            resp = await client.post(
                IMGUR_UPLOAD_URL,
                headers={"Authorization": f"Client-ID {IMGUR_CLIENT_ID}"},
                files={"image": f},
            )
        resp.raise_for_status()
        data = resp.json()
        if data.get("success"):
            url = data["data"]["link"]
            logger.info("Upload Imgur: %s → %s", file_path, url)
            return url
        raise InstagramAPIError(f"Imgur upload falhou: {data}")

"""CSV helpers that keep exported cells inert in spreadsheet applications."""

from __future__ import annotations

from typing import Any, Mapping


def spreadsheet_safe_cell(value: Any) -> Any:
    """Prefix formula-like strings so spreadsheet software treats them as text."""
    if not isinstance(value, str):
        return value
    candidate = value.lstrip(" \t\r\n")
    if candidate.startswith(("=", "+", "-", "@")):
        return "'" + value
    return value


def spreadsheet_safe_record(record: Mapping[str, Any]) -> dict[str, Any]:
    """Return a copy of *record* with every string cell neutralized."""
    return {key: spreadsheet_safe_cell(value) for key, value in record.items()}

"""
API REST e dashboard para dados do Instagram.

Uso:
    python scripts/serve_api.py
    python scripts/serve_api.py --port 8080 --host 0.0.0.0

Endpoints:
    GET /                           → info da API
    GET /api/posts                  → posts com filtros
    GET /api/comments               → comentários
    GET /api/insights/summary       → resumo de insights
    GET /api/insights/best-times    → melhores horários
    GET /api/stats                  → estatísticas gerais
    GET /api/export/{format}        → exportação
    GET /api/templates              → templates
    GET /api/actions                → audit log
    GET /dashboard                  → dashboard HTML
    GET /webhook                    → stub para v2
"""
from __future__ import annotations

import argparse
import csv
import io
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))

from config import STATIC_DIR
from csv_utils import spreadsheet_safe_record
from db import Database

try:
    from fastapi import FastAPI, Query
    from fastapi.responses import FileResponse, HTMLResponse, JSONResponse, PlainTextResponse, StreamingResponse
    import uvicorn
except ImportError:
    print("FastAPI não instalado. Execute: pip install fastapi uvicorn")
    sys.exit(1)

app = FastAPI(
    title="Instagram Dashboard API",
    description="API REST para dados e analytics do Instagram",
    version="1.0.0",
)

db = Database()
db.init()


@app.get("/", summary="Info da API")
def root():
    stats = db.get_stats()
    return {
        "name": "Instagram Dashboard API",
        "version": "1.0.0",
        "stats": stats,
        "endpoints": {
            "posts": "/api/posts",
            "comments": "/api/comments",
            "insights_summary": "/api/insights/summary",
            "insights_best_times": "/api/insights/best-times",
            "stats": "/api/stats",
            "templates": "/api/templates",
            "actions": "/api/actions",
            "dashboard": "/dashboard",
        },
    }


@app.get("/api/posts", summary="Lista posts")
def list_posts(
    status: str = Query(None, description="Filtrar por status"),
    limit: int = Query(50, ge=1, le=500),
    offset: int = Query(0, ge=0),
):
    account = db.get_active_account()
    account_id = account["id"] if account else None
    posts = db.get_posts(account_id=account_id, status=status, limit=limit, offset=offset)
    return {"total": len(posts), "data": posts}


@app.get("/api/comments", summary="Lista comentários")
def list_comments(
    media_id: str = Query(None),
    unreplied: bool = Query(False),
    limit: int = Query(50, ge=1, le=500),
):
    account = db.get_active_account()
    account_id = account["id"] if account else None
    comments = db.get_comments(
        ig_media_id=media_id,
        account_id=account_id,
        unreplied_only=unreplied,
        limit=limit,
    )
    return {"total": len(comments), "data": comments}


@app.get("/api/insights/summary", summary="Resumo de insights")
def insights_summary():
    conn = db._connect()
    # Engajamento médio por tipo de conteúdo
    rows = conn.execute("""
        SELECT p.media_type,
               COUNT(DISTINCT p.id) as post_count,
               AVG(CASE WHEN i.metric_name='engagement' THEN i.metric_value END) as avg_engagement,
               AVG(CASE WHEN i.metric_name='reach' THEN i.metric_value END) as avg_reach,
               AVG(CASE WHEN i.metric_name='impressions' THEN i.metric_value END) as avg_impressions
        FROM posts p
        LEFT JOIN insights i ON i.ig_media_id = p.ig_media_id
        WHERE p.status = 'published'
        GROUP BY p.media_type
    """).fetchall()

    return {"by_media_type": [dict(r) for r in rows]}


@app.get("/api/insights/best-times", summary="Melhores horários para postar")
def best_times():
    conn = db._connect()
    rows = conn.execute("""
        SELECT
            strftime('%H', p.published_at) as hour,
            strftime('%w', p.published_at) as weekday,
            COUNT(DISTINCT p.id) as post_count,
            AVG(i.metric_value) as avg_engagement
        FROM posts p
        JOIN insights i ON i.ig_media_id = p.ig_media_id
        WHERE p.status = 'published' AND p.published_at IS NOT NULL
          AND i.metric_name IN ('engagement', 'reach')
        GROUP BY hour, weekday
        ORDER BY avg_engagement DESC
    """).fetchall()

    weekday_names = ["Dom", "Seg", "Ter", "Qua", "Qui", "Sex", "Sáb"]
    data = []
    for r in rows:
        data.append({
            "hour": f"{r['hour']}:00" if r["hour"] else "?",
            "weekday": weekday_names[int(r["weekday"])] if r["weekday"] else "?",
            "posts": r["post_count"],
            "avg_engagement": round(r["avg_engagement"], 1) if r["avg_engagement"] else 0,
        })
    return {"data": data}


@app.get("/api/stats", summary="Estatísticas gerais")
def stats():
    return db.get_stats()


@app.get("/api/templates", summary="Templates de conteúdo")
def list_templates():
    templates = db.get_templates()
    return {"total": len(templates), "data": templates}


@app.get("/api/actions", summary="Audit log recente")
def recent_actions(limit: int = Query(50, ge=1, le=500)):
    actions = db.get_recent_actions(limit=limit)
    return {"total": len(actions), "data": actions}


@app.get("/api/export/json", summary="Exportar posts em JSON")
def export_json():
    account = db.get_active_account()
    posts = db.get_posts(account_id=account["id"] if account else None, limit=5000)
    return JSONResponse(
        content={"total": len(posts), "data": posts},
        headers={"Content-Disposition": "attachment; filename=instagram_posts.json"},
    )


@app.get("/api/export/csv", summary="Exportar posts em CSV")
def export_csv():
    account = db.get_active_account()
    posts = db.get_posts(account_id=account["id"] if account else None, limit=5000)
    if not posts:
        return PlainTextResponse("Sem dados.")
    output = io.StringIO()
    writer = csv.DictWriter(output, fieldnames=list(posts[0].keys()), extrasaction="ignore")
    writer.writeheader()
    writer.writerows(spreadsheet_safe_record(post) for post in posts)
    output.seek(0)
    return StreamingResponse(
        iter([output.getvalue()]),
        media_type="text/csv",
        headers={"Content-Disposition": "attachment; filename=instagram_posts.csv"},
    )


@app.get("/dashboard", summary="Dashboard visual")
def dashboard():
    dashboard_path = STATIC_DIR / "dashboard.html"
    if dashboard_path.exists():
        return FileResponse(dashboard_path, media_type="text/html")
    return HTMLResponse("<h1>Dashboard não encontrado</h1><p>Crie static/dashboard.html</p>")


@app.get("/webhook", summary="Webhook stub (v2)")
def webhook_stub():
    return {"status": "ok", "message": "Webhook endpoint ready (v2)"}


@app.post("/webhook", summary="Webhook receiver (v2)")
def webhook_receive():
    return {"status": "ok"}


def main():
    parser = argparse.ArgumentParser(description="API Instagram Dashboard")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--reload", action="store_true")
    args = parser.parse_args()

    print(f"\nAPI: http://{args.host}:{args.port}")
    print(f"Dashboard: http://{args.host}:{args.port}/dashboard")
    print(f"Docs: http://{args.host}:{args.port}/docs\n")

    uvicorn.run(
        "serve_api:app",
        host=args.host,
        port=args.port,
        reload=args.reload,
        app_dir=str(Path(__file__).parent),
    )


if __name__ == "__main__":
    main()

"""
Templates reutilizáveis de conteúdo para Instagram.

Uso:
    python scripts/templates.py --create --name "promo" --caption "Oferta: {produto}! {desconto}% OFF" --hashtags "#oferta,#promo"
    python scripts/templates.py --list
    python scripts/templates.py --show --name promo
    python scripts/templates.py --delete --name promo
    python scripts/templates.py --preview --name promo --vars produto=Tênis desconto=30
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))

from db import Database

db = Database()
db.init()


def create_template(name: str, caption: str, hashtags: str = None, schedule_time: str = None) -> None:
    """Cria ou atualiza um template."""
    hashtag_list = None
    if hashtags:
        hashtag_list = json.dumps([h.strip() for h in hashtags.split(",")])

    template_id = db.upsert_template({
        "name": name,
        "caption_template": caption,
        "hashtag_set": hashtag_list,
        "default_schedule_time": schedule_time,
    })
    print(json.dumps({
        "status": "created",
        "id": template_id,
        "name": name,
        "caption_template": caption,
        "hashtags": json.loads(hashtag_list) if hashtag_list else [],
    }, indent=2, ensure_ascii=False))


def list_templates() -> None:
    """Lista todos os templates."""
    templates = db.get_templates()
    for t in templates:
        if t.get("hashtag_set") and isinstance(t["hashtag_set"], str):
            try:
                t["hashtag_set"] = json.loads(t["hashtag_set"])
            except json.JSONDecodeError:
                pass
    print(json.dumps({"total": len(templates), "templates": templates}, indent=2, ensure_ascii=False))


def show_template(name: str) -> None:
    """Mostra detalhes de um template."""
    t = db.get_template_by_name(name)
    if not t:
        print(json.dumps({"error": f"Template '{name}' não encontrado"}, indent=2))
        return
    if t.get("hashtag_set") and isinstance(t["hashtag_set"], str):
        try:
            t["hashtag_set"] = json.loads(t["hashtag_set"])
        except json.JSONDecodeError:
            pass
    print(json.dumps(t, indent=2, ensure_ascii=False))


def delete_template(name: str) -> None:
    """Deleta um template."""
    if db.delete_template(name):
        print(json.dumps({"status": "deleted", "name": name}, indent=2))
    else:
        print(json.dumps({"error": f"Template '{name}' não encontrado"}, indent=2))


def preview_template(name: str, variables: list) -> None:
    """Preview de um template com variáveis aplicadas."""
    t = db.get_template_by_name(name)
    if not t:
        print(json.dumps({"error": f"Template '{name}' não encontrado"}, indent=2))
        return

    caption = t["caption_template"] or ""
    var_dict = {}
    for v in variables:
        if "=" in v:
            key, val = v.split("=", 1)
            var_dict[key.strip()] = val.strip()

    try:
        rendered = caption.format(**var_dict)
    except KeyError as e:
        print(json.dumps({"error": f"Variável faltando: {e}"}, indent=2))
        return

    hashtags = []
    if t.get("hashtag_set"):
        try:
            hashtags = json.loads(t["hashtag_set"]) if isinstance(t["hashtag_set"], str) else t["hashtag_set"]
        except json.JSONDecodeError:
            pass

    full_caption = rendered
    if hashtags:
        full_caption = f"{rendered}\n\n{' '.join(hashtags)}"

    print(json.dumps({
        "template": name,
        "variables": var_dict,
        "rendered_caption": full_caption,
    }, indent=2, ensure_ascii=False))


def main():
    parser = argparse.ArgumentParser(description="Templates de conteúdo Instagram")
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--create", action="store_true", help="Criar template")
    group.add_argument("--list", action="store_true", help="Listar templates")
    group.add_argument("--show", action="store_true", help="Ver template")
    group.add_argument("--delete", action="store_true", help="Deletar template")
    group.add_argument("--preview", action="store_true", help="Preview com variáveis")
    parser.add_argument("--name", help="Nome do template")
    parser.add_argument("--caption", help="Template de caption (use {var} para variáveis)")
    parser.add_argument("--hashtags", help="Hashtags separadas por vírgula")
    parser.add_argument("--schedule-time", help="Horário padrão (HH:MM)")
    parser.add_argument("--vars", nargs="+", help="Variáveis (key=value)")
    args = parser.parse_args()

    if args.create:
        if not args.name or not args.caption:
            parser.error("--name e --caption são obrigatórios com --create")
        create_template(args.name, args.caption, args.hashtags, args.schedule_time)
    elif args.list:
        list_templates()
    elif args.show:
        if not args.name:
            parser.error("--name é obrigatório com --show")
        show_template(args.name)
    elif args.delete:
        if not args.name:
            parser.error("--name é obrigatório com --delete")
        delete_template(args.name)
    elif args.preview:
        if not args.name:
            parser.error("--name é obrigatório com --preview")
        preview_template(args.name, args.vars or [])


if __name__ == "__main__":
    main()
